import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = []
            for _ in range(N):
                A.append(int(next(iterator)))
        except StopIteration:
            break

        from collections import Counter
        freq = Counter(A)

        max_count = 0
        if freq:
            max_count = max(freq.values())

        if max_count > N // 2:
            print("NO")
        else:
            print("YES")
            sorted_A = sorted(A)
            B = sorted_A

            half = N // 2
            C = sorted_A[half:] + sorted_A[:half]

            print(" ".join(map(str, B)))
            print(" ".join(map(str, C)))

if __name__ == "__main__":
    solve()
